function MillstoneDressingChalkMaker.init() MillstoneDressingChalkMaker.ironStock=10; MillstoneDressingChalkMaker.bronzeStock=8; MillstoneDressingChalkMaker.woodStock=18; MillstoneDressingChalkMaker.leatherStock=8; MillstoneDressingChalkMaker.silverStock=8; MillstoneDressingChalkMaker.goldStock=6; MillstoneDressingChalkMaker.jewelStock=4; MillstoneDressingChalkMaker.pearlStock=4; MillstoneDressingChalkMaker.productStock={}; MillstoneDressingChalkMaker.buildings={}; MillstoneDressingChalkMaker.maker=nil; MillstoneDressingChalkMaker.activeMaking={}; MillstoneDressingChalkMaker.totalProducts=0; MillstoneDressingChalkMaker.dayTimer=0; print("[MillstoneDressingChalkMaker] Royal Millstone Dressing Chalk Maker System initialized (6 products, 4 buildings)") end
function MillstoneDressingChalkMaker.hireMaker(n,s) s=s or math.random(55,90); local c=570+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; MillstoneDressingChalkMaker.maker={name=n or ("Kredar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Kredar najet: %s (spretnost: %d)",MillstoneDressingChalkMaker.maker.name,s),"success") end; return true end
function MillstoneDressingChalkMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function MillstoneDressingChalkMaker.build(id) local ok,e=MillstoneDressingChalkMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(MillstoneDressingChalkMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function MillstoneDressingChalkMaker.getQualityBonus() local b=0; for _,bd in ipairs(MillstoneDressingChalkMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function MillstoneDressingChalkMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and MillstoneDressingChalkMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.bronzeCost and MillstoneDressingChalkMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.woodCost and MillstoneDressingChalkMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and MillstoneDressingChalkMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and MillstoneDressingChalkMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and MillstoneDressingChalkMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and MillstoneDressingChalkMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and MillstoneDressingChalkMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #MillstoneDressingChalkMaker.buildings==0 then return false,"Potrebna kredna delavnica" end; if not MillstoneDressingChalkMaker.maker then return false,"Potreben kredar" end; return true end
function MillstoneDressingChalkMaker.make(pt,qty) qty=qty or 1; local ok,e=MillstoneDressingChalkMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then MillstoneDressingChalkMaker.ironStock=MillstoneDressingChalkMaker.ironStock-d.ironCost*qty end; if d.bronzeCost then MillstoneDressingChalkMaker.bronzeStock=MillstoneDressingChalkMaker.bronzeStock-d.bronzeCost*qty end; if d.woodCost then MillstoneDressingChalkMaker.woodStock=MillstoneDressingChalkMaker.woodStock-d.woodCost*qty end; if d.leatherCost then MillstoneDressingChalkMaker.leatherStock=MillstoneDressingChalkMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then MillstoneDressingChalkMaker.silverStock=MillstoneDressingChalkMaker.silverStock-d.silverCost*qty end; if d.goldCost then MillstoneDressingChalkMaker.goldStock=MillstoneDressingChalkMaker.goldStock-d.goldCost*qty end; if d.jewelCost then MillstoneDressingChalkMaker.jewelStock=MillstoneDressingChalkMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then MillstoneDressingChalkMaker.pearlStock=MillstoneDressingChalkMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if MillstoneDressingChalkMaker.maker then t=math.max(1,t-math.floor(MillstoneDressingChalkMaker.maker.skill/13)) end; table.insert(MillstoneDressingChalkMaker.activeMaking,{id="millstonedressingchalk_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function MillstoneDressingChalkMaker.completeMaking(m) local q=1.0+(MillstoneDressingChalkMaker.getQualityBonus()/100); if MillstoneDressingChalkMaker.maker then q=q+(MillstoneDressingChalkMaker.maker.skill/140) end; q=math.min(2.5,q); MillstoneDressingChalkMaker.productStock[m.productType]=(MillstoneDressingChalkMaker.productStock[m.productType] or 0)+m.quantity; MillstoneDressingChalkMaker.totalProducts=MillstoneDressingChalkMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if MillstoneDressingChalkMaker.maker then MillstoneDressingChalkMaker.maker.itemsMade=MillstoneDressingChalkMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then MillstoneDressingChalkMaker.maker.skill=math.min(100,MillstoneDressingChalkMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Kreda izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"millstonedressingchalk.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
function MillstoneDressingChalkMaker.update(dt) if not _G.state then return end; MillstoneDressingChalkMaker.dayTimer=MillstoneDressingChalkMaker.dayTimer+dt; if MillstoneDressingChalkMaker.dayTimer>=30 then MillstoneDressingChalkMaker.dayTimer=0; for i=#MillstoneDressingChalkMaker.activeMaking,1,-1 do local m=MillstoneDressingChalkMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then MillstoneDressingChalkMaker.completeMaking(m); table.remove(MillstoneDressingChalkMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(MillstoneDressingChalkMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if MillstoneDressingChalkMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function MillstoneDressingChalkMaker.getStats() return {ironStock=MillstoneDressingChalkMaker.ironStock,bronzeStock=MillstoneDressingChalkMaker.bronzeStock,woodStock=MillstoneDressingChalkMaker.woodStock,leatherStock=MillstoneDressingChalkMaker.leatherStock,silverStock=MillstoneDressingChalkMaker.silverStock,goldStock=MillstoneDressingChalkMaker.goldStock,jewelStock=MillstoneDressingChalkMaker.jewelStock,pearlStock=MillstoneDressingChalkMaker.pearlStock,productStock=MillstoneDressingChalkMaker.productStock,numBuildings=#MillstoneDressingChalkMaker.buildings,hasMaker=MillstoneDressingChalkMaker.maker~=nil,makerName=MillstoneDressingChalkMaker.maker and MillstoneDressingChalkMaker.maker.name or "—",makerSkill=MillstoneDressingChalkMaker.maker and MillstoneDressingChalkMaker.maker.skill or 0,activeMaking=#MillstoneDressingChalkMaker.activeMaking,totalProducts=MillstoneDressingChalkMaker.totalProducts} end
